{
  "title": "Broken-grid electronic groove",
  "tempo_map": [
    {
      "bar": 1,
      "bpm": 80
    }
  ],
  "key_map": [
    {
      "bar": 1,
      "key": "D minor"
    }
  ],
  "sections": [
    {
      "id": "establish",
      "start_bar": 1,
      "bars": 4,
      "time_signature": "4/4"
    },
    {
      "id": "variation",
      "start_bar": 5,
      "bars": 4,
      "time_signature": "4/4"
    }
  ],
  "track_plan": [
    {
      "id": "kick",
      "name": "Kick",
      "role": "kick",
      "register": {
        "low": 35,
        "high": 36
      },
      "instrument_hint": "Electronic Kick",
      "section_jobs": [
        {
          "section_id": "establish",
          "intent": "Place syncopated kick hits on offbeats, leaving some downbeats open",
          "density": "sparse"
        },
        {
          "section_id": "variation",
          "intent": "Vary kick placement with an added pickup before beat 3, still avoid four-on-the-floor",
          "density": "medium"
        }
      ]
    },
    {
      "id": "percussion",
      "name": "Percussion",
      "role": "percussion",
      "register": {
        "low": 37,
        "high": 42
      },
      "instrument_hint": "Electronic Percussion",
      "section_jobs": [
        {
          "section_id": "establish",
          "intent": "Layer closed hats, clap or snare on backbeats, and ghost rim hits",
          "density": "medium"
        },
        {
          "section_id": "variation",
          "intent": "Add syncopated accent layers and increase rhythmic activity without random fills",
          "density": "dense"
        }
      ]
    },
    {
      "id": "sub_bass",
      "name": "Sub Bass",
      "role": "bass",
      "register": {
        "low": 28,
        "high": 43
      },
      "instrument_hint": "Sub Bass",
      "section_jobs": [
        {
          "section_id": "establish",
          "intent": "Lock with kick on selected offbeat placements, provide low-end motion without masking every downbeat",
          "density": "medium"
        },
        {
          "section_id": "variation",
          "intent": "Reduce rhythmic density by using longer held notes, letting harmony and percussion carry the variation",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "chord_stab",
      "name": "Chord Stab",
      "role": "harmony",
      "register": {
        "low": 48,
        "high": 65
      },
      "instrument_hint": "Synth Stab",
      "section_jobs": [
        {
          "section_id": "establish",
          "intent": "Place short chord stabs on offbeat eighths, contrast bass and kick rhythm",
          "density": "sparse"
        },
        {
          "section_id": "variation",
          "intent": "Double a syncopated signature accent with a chord stab, increase harmonic rhythm slightly",
          "density": "medium"
        }
      ]
    },
    {
      "id": "short_motif",
      "name": "Short Motif",
      "role": "melody",
      "register": {
        "low": 60,
        "high": 76
      },
      "instrument_hint": "FM Pluck",
      "section_jobs": [
        {
          "section_id": "establish",
          "intent": "Introduce a two-note syncopated motif with rests, avoiding downbeats",
          "density": "sparse"
        },
        {
          "section_id": "variation",
          "intent": "Develop the motif rhythmically, adding one extra note and shifting its placement to second half of bar",
          "density": "medium"
        }
      ]
    }
  ],
  "motif_strategy": "A short two-note syncopated motif acts as identity. It first appears in bars 1-2, rests in bar 3, returns transposed in bar 4. In the variation section, the motif is rhythmically displaced and gains a third note, but remains sparse enough to avoid becoming a lead line.",
  "harmony_strategy": "Harmony comes from sparse chord stabs on offbeat eighths, using D minor pentatonic collection with occasional B-flat major implied by the bass. Chord stabs never sustain, leaving space for kick and bass. The variation section adds a second stab per phrase on a syncopated accent.",
  "groove_strategy": "Kick and bass form a broken grid: kick hits on offbeats and syncopated placements, bass locks to selected kick hits but leaves downbeats open. Percussion layers a steady but varied sixteenth-note feel with clap/snare on backbeats. The variation increases percussion density while bass becomes sparser, creating a push-pull between sections."
}
